/**
 * External dependencies
 */
import type { ConversionAction } from '@nab/types';

export type PageViewTriggersAction = SetPageViewTriggers;

export function setPageViewTriggerActions(
	actions: ReadonlyArray< ConversionAction >
): SetPageViewTriggers {
	return {
		type: 'SET_PAGE_VIEW_TRIGGERS',
		actions,
	};
}

// =====
// TYPES
// =====

type SetPageViewTriggers = {
	readonly type: 'SET_PAGE_VIEW_TRIGGERS';
	readonly actions: ReadonlyArray< ConversionAction >;
};
