/**
 * WordPress dependencies
 */
import { createSelector } from '@safe-wordpress/data';

/**
 * External dependencies
 */
import { values } from 'lodash';
import { isDefined } from '@nab/utils';
import type { ConversionAction } from '@nab/types';

/**
 * Internal dependencies.
 */
import type { State } from '../types';

export const getPageViewTriggers = createSelector(
	( state: State ): ReadonlyArray< ConversionAction > =>
		values( state.experiment.pageViewTriggers ).filter( isDefined ),
	( state: State ) => [ state.experiment.pageViewTriggers ]
);
