/**
 * WordPress dependencies
 */
import {
	Button,
	CheckboxControl,
	TextControl,
} from '@safe-wordpress/components';
import { useDispatch, useSelect } from '@safe-wordpress/data';
import { useEffect, useState } from '@safe-wordpress/element';
import { _x } from '@safe-wordpress/i18n';

/**
 * External dependencies
 */
import { usePluginSetting } from '@nab/data';
import type { Goal as RealGoal, Maybe } from '@nab/types';
type Goal = Omit< RealGoal, 'conversionActions' >;

/**
 * Internal dependencies
 */
import './style.scss';
import { store as NAB_EDITOR } from '../../../store';

type GA4GoalSettings = Required<
	Required< RealGoal >[ 'attributes' ]
>[ 'ga4' ];

export function GA4Settings(): JSX.Element | null {
	const isGA4TrackingEnabled = usePluginSetting( 'isGA4TrackingEnabled' );
	const [ settings, setSettings ] = useGA4Settings();
	const {
		disabled: isGA4GoalTrackingDisabled,
		eventName: ga4EventName,
		goalName: ga4GoalName,
	} = settings;

	const disableGA4Tracking = ( disabled: boolean ) =>
		setSettings( { ...settings, disabled } );
	const setGA4EventName = ( eventName: string ) =>
		setSettings( {
			...settings,
			eventName,
		} );
	const setGA4GoalName = ( goalName: string ) =>
		setSettings( {
			...settings,
			goalName,
		} );

	const [ areDetailsVisible, showDetails ] = useState(
		! isGA4GoalTrackingDisabled && !! ( ga4EventName || ga4GoalName )
	);

	useEffect( () => {
		if ( isGA4GoalTrackingDisabled ) {
			showDetails( false );
			return;
		}
		if ( areDetailsVisible ) {
			return;
		}
		showDetails( !! ( ga4EventName || ga4GoalName ) );
	}, [
		areDetailsVisible,
		isGA4GoalTrackingDisabled,
		ga4EventName,
		ga4GoalName,
	] );

	if ( ! isGA4TrackingEnabled ) {
		return null;
	}

	return (
		<div className="nab-current-goal-info__ga4">
			<CheckboxControl
				label={
					<>
						{ _x(
							'Track this goal’s conversions in Google Analytics',
							'command',
							'nelio-ab-testing'
						) }{ ' ' }
						{ ! isGA4GoalTrackingDisabled &&
							! areDetailsVisible && (
								<Button
									variant="link"
									onClick={ () => showDetails( true ) }
								>
									{ _x(
										'(customize)',
										'command',
										'nelio-ab-testing'
									) }
								</Button>
							) }
					</>
				}
				checked={ ! isGA4GoalTrackingDisabled }
				onChange={ ( checked ) => disableGA4Tracking( ! checked ) }
			/>
			{ areDetailsVisible && (
				<div className="nab-current-goal-info__ga4-details">
					<TextControl
						label={ _x( 'Event Name', 'text', 'nelio-ab-testing' ) }
						placeholder="conversion"
						value={ ga4EventName }
						onChange={ setGA4EventName }
					/>
					<TextControl
						label={ _x( 'Goal Name', 'text', 'nelio-ab-testing' ) }
						value={ ga4GoalName }
						onChange={ setGA4GoalName }
					/>
				</div>
			) }
		</div>
	);
}

// =====
// HOOKS
// =====

const DEFAULT_SETTINGS: GA4GoalSettings = {
	disabled: false,
	eventName: '',
	goalName: '',
};

function useGA4Settings(): [
	GA4GoalSettings,
	( settings: Partial< GA4GoalSettings > ) => void,
] {
	const goal = useGoal();
	const { updateGoal } = useDispatch( NAB_EDITOR );
	if ( ! goal ) {
		return [ DEFAULT_SETTINGS, () => void null ];
	}

	const settings = goal?.attributes.ga4 || DEFAULT_SETTINGS;
	const setSettings = ( newSettings: Partial< GA4GoalSettings > ) =>
		updateGoal( goal.id, { ga4: { ...settings, ...newSettings } } );
	return [ settings, setSettings ];
}

const useGoal = (): Maybe< Goal > =>
	useSelect( ( select ) => select( NAB_EDITOR ).getActiveGoal(), [] );
